    result = harness(action)
    print("harness(action_dict):", result)
except Exception as e:
    print("harness(action_dict) error:", type(e).__name__, e)

# Pattern 2: harness(action="submit_grid")
try:
    result = harness(action="submit_grid")
    print("harness(action='submit_grid'):", result)
except Exception as e:
    print("harness(action='submit_grid') error:", type(e).__name__, e)

# Pattern 3: Just harness() no args
try:
    result = harness()
    print("harness():", result)
except Exception as e:
    print("harness() error:", type(e).__name__, e)

